changeSet.sql:
DO $$
DECLARE
    first_month TIMESTAMPTZ;
    last_month TIMESTAMPTZ;
    m TIMESTAMPTZ;
BEGIN
    PERFORM set_config('TimeZone', 'UTC', true);
    first_month := date_trunc('month', LEAST(
        COALESCE((SELECT min(created_at) FROM tasks_unpartitioned), now()),
        now() - INTERVAL '25 months'));
    last_month := date_trunc('month', now()) + INTERVAL '3 months';
    m := first_month;
    WHILE m <= last_month LOOP
        EXECUTE format('CREATE TABLE %I PARTITION OF tasks FOR VALUES FROM (%L) TO (%L)',
                       'tasks_' || to_char(m, 'YYYY_MM'), m, m + INTERVAL '1 month');
        m := m + INTERVAL '1 month';
    END LOOP;
END $$
